// Define your NumberExpression interface here
interface NumberExpression {
  value: number;
}

interface AdditionExpression {
  left: Expression;
  right: Expression;
}

// Create the Expression union type here
type Expression = NumberExpression | AdditionExpression;

// Define the Visitor interface here
interface Visitor<T> {
  visitNumber(expr: NumberExpression): T;
  visitAddition(expr: AdditionExpression): T;
}

// Create the NumberExpression class here
class NumberExpression implements NumberExpression {
  constructor(public value: number) {}

  accept<T>(visitor: Visitor<T>): T {
    return visitor.visitNumber(this);
  }
}

// Create the AdditionExpression class here
class AdditionExpression implements AdditionExpression {
  constructor(public left: Expression, public right: Expression) {}

  accept<T>(visitor: Visitor<T>): T {
    return visitor.visitAddition(this);
  }
}

// Create the EvaluatorVisitor class here
class EvaluatorVisitor implements Visitor<number> {
  visitNumber(expr: NumberExpression): number {
    return expr.value;
  }

  visitAddition(expr: AdditionExpression): number {
    return expr.left.accept(this) + expr.right.accept(this);
  }
}

// Create the PrinterVisitor class here
class PrinterVisitor implements Visitor<string> {
  visitNumber(expr: NumberExpression): string {
    return expr.value.toString();
  }

  visitAddition(expr: AdditionExpression): string {
    return `(${expr.left.accept(this)} + ${expr.right.accept(this)})`;
  }
}

